    ("Contracts",[("Interim agreement with Sobha for October–March with a rate card and headcount","Secretary","Sep"),("Facility-management tender with service standards from the survey","Secretary, engineering group","before SGBM"),("Security: written position on deployment, penalties applied, retender specification","Secretary","Sep–Oct"),("Lift contract rebid on uptime; monthly lift log published from October","Engineering group","Oct"),("STP: odour audit, retender with standards","Engineering group","Oct")]),
