    arows="".join('<section><h2>'+g+'</h2><div class="tablewrap"><table><thead><tr><th>Action</th><th>Who</th><th>When</th></tr></thead><tbody>'+"".join('<tr><td>'+a+'</td><td>'+w+'</td><td>'+d+'</td></tr>' for a,w,d in items)+'</tbody></table></div></section>' for g,items in ACT)
    act='<section><div class="eyebrow">The committee\'s commitments, in public</div><h1>What the committee is doing</h1><p class="lead">Every item has an owner and a date. Progress is marked here each month. Anything that slips stays on the list with its reason.</p></section>'+arows+'<section><p class="small">"Engineering group" is the volunteer engineering sub-committee; "facility manager" is Sobha\'s estate manager working to the committee\'s instructions. Personal names are not used on these pages.</p></section>'
